        }
        dp[0][0] = 0;

        for (int i = 0; i < n; i++) {
            int val = p[i];
            // Update DP backwards in j to avoid using the same element multiple times
            for (int j = Math.min(i, k - 1); j >= 0; j--) {
                int costStep = Math.abs(initialPos[j] - i);
                int limit = maxCost - costStep;
                for (int c = 0; c <= limit; c++) {
                    int prev = dp[j][c];
                    if (prev != -1) {
                        int nc = c + costStep;
                        int nv = prev + val;
                        if (nv > dp[j + 1][nc]) {
                            dp[j + 1][nc] = nv;
                        }
                    }
                }
            }
        }

        int ans = 0;
        for (int c = 0; c <= maxCost; c++) {
            if (dp[k][c] > ans) {
                ans = dp[k][c];
            }
        }

        System.out.println(ans);
    }
