Uma solução eficiente e correta em **JavaScript (Node.js)** para o problema **Brigadeiros**.

### Abordagem

O problema consiste em escolher $K$ novas posições $1 \le j_1 < j_2 < \dots < j_K \le N$ para os $K$ amigos de modo a maximizar a soma dos brigadeiros $\sum P_{j_i}$, respeitando o limite de trocas $\sum |pos_i - j_i| \le T$.

Como cada prato tem entre $0$ e $9$ brigadeiros, a soma máxima possível é $9 \times K \le 2700$. Em vez de usar as trocas como dimensão da Programação Dinâmica (já que $T$ pode ser grande), invertemos o estado e minimizamos o custo em trocas para alcançar cada possível soma de brigadeiros $s$:

- Seja $dp[i][s]$ o menor número de trocas necessárias para posicionar os primeiros $i$ amigos até a posição atual da mesa, totalizando uma soma de $s$ brigadeiros.
- Conforme percorremos cada posição $p$ de $1$ a $N$, decidimos se alocamos o $i$-ésimo amigo nessa posição. Se alocarmos, a transição é:
  $$dp[i][s] = \min(dp[i][s], dp[i - 1][s - P_p] + |pos_i - p|)$$
- Limitando o intervalo de $i$ viável para cada $p$ ($\max(1, K - N + p) \le i \le \min(p, K)$), o número total de operações fica na ordem de $\approx 1.5 \times 10^7$, executando em poucos milissegundos.

Ao final, a resposta é a maior soma $s$ tal que $dp[K][s] \le T$.

### Código em JavaScript

```javascript
const fs = require('fs');

function solve() {
  const buffer = fs.readFileSync(0);
  let offset = 0;

  function nextInt() {
    while (offset < buffer.length && buffer[offset] <= 32) {
      offset++;
    }
    if (offset >= buffer.length) return null;
    let res = 0;
    while (offset < buffer.length && buffer[offset] > 32) {
      res = res * 10 + (buffer[offset] - 48);
      offset++;
    }
    return res;
  }

  const N = nextInt();
  if (N === null) return;
  const K = nextInt();
  const T = nextInt();

  const P = new Int32Array(N + 1);
  for (let i = 1; i <= N; i++) {
    P[i] = nextInt();
  }

  const pos = new Int32Array(K + 1);
  let kIdx = 1;
  for (let i = 1; i <= N; i++) {
    const g = nextInt();
    if (g === 1) {
      pos[kIdx++] = i;
    }
  }

  const maxS = 9 * K;
  const stride = maxS + 1;
  const INF = 1000000001;

  // dp[i * stride + s] armazena o menor custo para i amigos com soma s
  const dp = new Int32Array((K + 1) * stride).fill(INF);
  dp[0] = 0;

  for (let p = 1; p <= N; p++) {
    const v = P[p];
    const minI = Math.max(1, K - (N - p));
    const maxI = Math.min(p, K);

    for (let i = maxI; i >= minI; i--) {
      const dist = Math.abs(pos[i] - p);
      const currRow = i * stride;
      const prevRow = (i - 1) * stride;
      const maxVal = i * 9;

      for (let s = maxVal; s >= v; s--) {
        const prevCost = dp[prevRow + (s - v)];
        if (prevCost !== INF) {
          const cost = prevCost + dist;
          if (cost < dp[currRow + s]) {
            dp[currRow + s] = cost;
          }
        }
      }
    }
  }

  let ans = 0;
  const rowK = K * stride;
  for (let s = maxS; s >= 0; s--) {
    if (dp[rowK + s] <= T) {
      ans = s;
      break;
    }
  }

  console.log(ans);
}

solve();
